using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CursedSandsEffect", menuName = "Data/Battle/Effects/Enemy/CursedSands Effect")]
public class CursedSandsEffect : Effect
{
	[Header("Lose Sands Of Time")]
	[SerializeField]
	private int loseCursedSandsOnActivationAmount;

	[SerializeField]
	private int minCursedSandsAmount;

	[SerializeField]
	private int madnessHexAmount;

	[SerializeField]
	private HexAction madnessHexAction;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnRollDices;

	[Header("Reroll Action")]
	[SerializeField]
	private IntReference diceToRerollAmountIntReference;

	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	[Header("Description")]
	[SerializeField]
	private SandsOfTimeEffect sandsOfTimeEffect;

	public int LoseCursedSandsOnActivationAmount => loseCursedSandsOnActivationAmount;

	public int MinCursedSandsAmount => minCursedSandsAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedAtTheStartOfTheBattle = base.localizationManager.GetLocalizedAtTheStartOfTheBattle(withSpace: true);
		string text = madnessHexAction.GetActionDescription(madnessHexAmount).LowercaseFirst();
		string text2 = localizedAtTheStartOfTheBattle + text + "\n";
		string text3 = amount.ToString();
		if (amount == EffectsValues.NO_VALUE)
		{
			text3 = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX();
		}
		string text4 = Smart.Format(sandsOfTimeEffect.GetLocalizedDescriptionExternal(), text3, base.localizationManager.GetLocalizedThenDecreaseEffect(this, loseCursedSandsOnActivationAmount), minCursedSandsAmount, 1);
		string text5 = Smart.Format(base.localizationManager.GetLocalizedWheneverYouPlayA(), base.localizationManager.GetLocalizedString("HexDie")) + base.localizationManager.GetLocalizedSpace() + text4;
		if (amount == EffectsValues.NO_VALUE)
		{
			return text5;
		}
		return text2 + text5;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		madnessHexAction.CastAmount(madnessHexAmount, effectOwner);
	}

	public bool CheckCursedSands(DiceInstance diceInstance, int chanceAmount, UnitEffects unitEffects)
	{
		if (RandomUtilities.RandomChance(Mathf.Min(chanceAmount, 100)))
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 2f, delegate
			{
				int num = unitEffects.IsEffectActiveGetAmount(this);
				int num2 = loseCursedSandsOnActivationAmount;
				if (num - loseCursedSandsOnActivationAmount < minCursedSandsAmount)
				{
					num2 = num - minCursedSandsAmount;
				}
				if (num2 > 0)
				{
					unitEffects.IsEffectActiveAndDecreaseEffect(this, loseCursedSandsOnActivationAmount);
				}
			});
			SpawnSecondVFX(GetVFXOwnerPosition(unitEffects.gameObject), 5f);
			unitEffects.GetComponent<SpriteControl>().PlayAnimationForced(AnimationType.Skill, AnimationChangeType.ReturnToIdleAnimation);
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().OnRerollEffects(1);
			List<DiceInstance> list = new List<DiceInstance>();
			list.Add(diceInstance);
			ReferenceSingleton<MiscOmensHandler>.Instance.ActivateRerollOmens(list);
			RollDie(diceInstance);
			ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
			return true;
		}
		return false;
	}

	private void RollDie(DiceInstance diceInstance)
	{
		ReferenceSingleton<DiceRollingHandler>.Instance.RollDieWithDieSetup(new List<DiceInstance> { diceInstance });
	}
}
